:root {
  --bg: #f7f8fa;
  --fg: #1d2230;
  --muted: #5a6478;
  --line: #d9dee8;
  --accent: #2f5bd7;
  --card: #ffffff;
}

* {
  box-sizing: border-box;
}

html {
  font-size: 16px;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: "Hiragino Kaku Gothic ProN", "Yu Gothic", Meiryo, sans-serif;
  line-height: 1.8;
}

.wrap {
  max-width: 46rem;
  margin: 0 auto;
  padding: 0 1.25rem;
}

.site-header {
  background: var(--card);
  border-bottom: 1px solid var(--line);
}

.site-title {
  font-size: 1.05rem;
  font-weight: 700;
  margin: 0;
  padding: 1rem 0 0.25rem;
}

.nav ul {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin: 0;
  padding: 0 0 0.9rem;
}

.nav a {
  color: var(--muted);
  text-decoration: none;
  font-size: 0.95rem;
  padding-bottom: 0.15rem;
  border-bottom: 2px solid transparent;
}

.nav a:hover {
  color: var(--accent);
}

.nav a[aria-current="page"] {
  color: var(--accent);
  border-bottom-color: var(--accent);
  font-weight: 700;
}

main {
  padding: 2rem 0 3rem;
}

h1 {
  font-size: 1.75rem;
  line-height: 1.45;
  margin: 0 0 0.75rem;
}

