  font-size: 1.25rem;
  margin: 2.25rem 0 0.75rem;
  padding-bottom: 0.35rem;
  border-bottom: 1px solid var(--line);
}

h3 {
  font-size: 1.05rem;
  margin: 1.5rem 0 0.5rem;
}

p {
  margin: 0.75rem 0;
}

a {
  color: var(--accent);
}

.lead {
  font-size: 1.05rem;
  color: var(--muted);
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 1rem 1.25rem;
  margin: 1rem 0;
}

.note {
  border-left: 4px solid var(--accent);
  background: var(--card);
  padding: 0.75rem 1rem;
  margin: 1.25rem 0;
}

